        push({ line: 2, op: "PushBack", x: num, mark: { i: t, cls: "calc" }, info: "PushBack(" + num + "): tail = (head + size) % " + cap + " = (" + head + " + " + size + ") % " + cap + " = " + t });
        // запись и size++ — разные строки листинга, у каждой свой кадр
