    var mR = {}; mR[k] = {}; mR[k][i2] = "found";
    push({ line: 3, snap: snap(mR), blkA: [l, l + (1 << k) - 1], blkB: [i2, r], k: k, a: a, b: b, info: "table[" + k + "][" + i2 + "] = " + b + " — минимум на ПРАВОМ блоке [" + i2 + ".." + r + "], тоже длины 2^" + k + ". Два блока ПЕРЕКРЫВАЮТСЯ и вместе покрывают [" + l + "," + r + "]" });
