        steps.push(snap({ lo: i, hi: hiJ, line: 4, vars: vb({ i: i, j: (j < n ? j : "—"), k: k }), info: "выдано №" + order.length + ": a[" + i + "]=" + a[i] + " из левой половины (она ≤ правой)" }));
        i++;
