        emitted[j] = true; order.push(a[j]);
        steps.push(snap({ lo: hiI, hi: j, line: 6, vars: vb({ i: (i < mid ? i : "—"), j: j, k: k }), info: "выдано №" + order.length + ": a[" + j + "]=" + a[j] + " из правой половины (она меньше)" }));
