    steps.push(snap({ lo: -1, hi: -1, done: true, line: 9, vars: vb({ i: i, j: j, k: n }), info: "Слияние за O(n): " + cmp + " сравнений, выдано " + order.length + " → [" + order.join(", ") + "]" }));
