      steps.push(snap({ lo: l, hi: r, upd: [l, r], delta: d, ptrNames: { lo: "u[0]", hi: "u[1]" }, dPlus: l, line: 3, vars: { u: us, i: "—", run: "—" }, info: "Обновление " + us + ": diff[" + l + "] += " + fmtNum(d) + " — с индекса " + l + " всё дальше станет на " + Math.abs(d) + (d < 0 ? " меньше" : " больше") }));
