          var oldEl = mkEl("div", "algo-tp__casold"); row.appendChild(oldEl);
          var evs = mkEl("div", "algo-tp__casevs"); row.appendChild(evs);
          host.appendChild(row); lanes[g] = { row: row, old: oldEl, evs: evs };
