      stepCard: function (s) { if (s.done) return { a: "корень", b: s.vars.root, c: "✓", cls: "eq" }; return { a: "узел " + s.vars.node, b: "к корню", c: "↑", cls: "lt" }; },
      varsOf: function (s) { return { "x": s.vars.x, "root": s.vars.root }; },
      customViz: ufViz
